//! Toolbar commands and panel layout.
//!
//! Panel order and contents follow the structure extracted from Fusion's
//! toolbar definition (see docs/spec, generated by
//! tools/extract_fusion_ui_spec.py). Labels and descriptions here are our own.
//! Entries Fission doesn't implement yet are listed as `Planned`, so the
//! dropdowns double as a roadmap.

use super::icons::Icon;
use crate::app::FissionApp;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Command {
    Sketch,
    Extrude,
    Revolve,
    Hole,
    Box,
    Cylinder,
    Sphere,
    Thread,
    Coil,
    Torus,
    Fillet,
    Chamfer,
    Shell,
    Draft,
    Scale,
    SplitBody,
    PressPull,
    OffsetFace,
    DeleteFace,
    RemoveFaces,
    TangentPlane,
    PlaneTwoEdges,
    PlaneThreePoints,
    AxisPerpendicular,
    AxisTwoPoints,
    PointVertex,
    PointTwoEdges,
    PointThreePlanes,
    PointCenter,
    PointEdgePlane,
    Combine,
    Canvas,
    Move,
    Joint,
    Interference,
    Mirror,
    PatternRect,
    PatternCirc,
    ExportStl,
    ExportStep,
    Export3mf,
    ExportObj,
    OffsetPlane,
    PlaneAtAngle,
    Midplane,
    AxisCylinder,
    AxisEdge,
    AxisTwoPlanes,
    Measure,
    Parameters,
    Sweep,
    Loft,
    Section,
    Appearance,
}

